root=Path.cwd();evidence=root/'validation/mesh';out=root/'output/pdf';out.mkdir(parents=True,exist_ok=True)
rows=json.loads((evidence/'mesh_metrics.json').read_text());lookup={r['scene']:r for r in rows};styles=getSampleStyleSheet()
