def fig(scene,name,w=244,h=138):return Image(str(evidence/scene/name),width=w,height=h,kind='proportional')
def table(data,widths):
 t=Table(data,colWidths=widths,hAlign='LEFT');t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#e9eef1')),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTNAME',(0,1),(-1,-1),'Helvetica'),('FONTSIZE',(0,0),(-1,-1),8.5),('LEADING',(0,0),(-1,-1),11),('TOPPADDING',(0,0),(-1,-1),6),('BOTTOMPADDING',(0,0),(-1,-1),6),('VALIGN',(0,0),(-1,-1),'TOP'),('LINEBELOW',(0,0),(-1,0),.5,colors.HexColor('#778899'))]));return t
story=[]
story += [P('Surface reconstruction','TitleMesh'),P('Mesh add-on | 3D Computer Vision | 14 November 2026','CaptionMesh'),P('Report integration material','SectionMesh'),P('This addendum documents the implemented mesh stage and measured local validation. It is intended for the full course report; it is not a claim that the complete IEEE report, narrated course demo or portal submission is finished.'),table([[P('1. Existing SfM','CaptionMesh'),P('2. Aligned depth','CaptionMesh'),P('3. Colored surface','CaptionMesh')],[P('Input images, intrinsics, world-to-camera poses, sparse points and tracks.','CaptionMesh'),P('Learned inverse depth with scale/shift fit, or calibrated stereo depth.','CaptionMesh'),P('Depth filtering, TSDF integration, marching cubes, cleanup and decimation.','CaptionMesh')]],[165,165,165]),Spacer(1,12),P('Method','SectionMesh'),P('The adapter retains the SfM frame: x_cam = R X + t and C = -R<super>T</super>t. It checks tracked reprojections before fusion. Depth Anything V2 Small predicts relative inverse depth. RANSAC followed by least squares fits 1/z_sfm = s d_rel + b, requiring at least 30 inliers and median relative depth residual below 10%. SGBM uses the recovered baseline directly.'),P('Invalid pixels, depth edges, sparse-object bounds and multi-view depth checks remove unsupported surfaces. Open3D integrates RGB-D with world-to-camera extrinsics. Voxel length is scene extent divided by voxel_div; the truncation band is four voxels. TSDF accumulates observations through a weighted running average. Marching cubes extracts the zero surface, followed by cleanup and an approximately 80k-triangle light mesh.'),Table([[fig('chair_sgbm_wide_roi','colored_0.png'),fig('chair_sgbm_wide_roi','shaded_0.png')]],colWidths=[250,250]),P('Chair triangle mesh: colored and shaded. Uses existing COLMAP poses, SGBM depth and a wider sparse ROI for thin legs. It is not our SfM pose result and remains non-watertight.','CaptionMesh'),PageBreak()]
story += [P('Measured validation','TitleMesh'),P('Every value below is read from saved JSON/CSV run outputs.','CaptionMesh')]
data=[['Run','Fuse','Full tris','Cov.','PSNR','SSIM','Time s']]
for name in ['temple_mono','sample_mono','sample_sgbm','sample_cached','chair_sgbm_wide_roi','car_sgbm','sphere_cached']:
 r=lookup[name];data.append([name,str(r['fused']),f"{r['full_faces']:,}",f"{r['coverage']:.3f}",f"{r['psnr_db']:.2f}",f"{r['ssim']:.3f}",f"{r['seconds']:.2f}"])
story += [table(data,[163,35,67,50,55,55,55]),Spacer(1,10),P('Cov. = mean fraction of image pixels hit by the rendered surface. Image metrics use held-out registered views excluded from depth generation, stereo neighbors, consistency checks and fusion. SfM poses and sparse structure still use all images: this is a held-out fusion check, not a fully held-out SfM experiment. SSIM uses fully hit windows.','CaptionMesh'),P('Temple and the generated tile fixture use our SfM poses. Chair and car use existing COLMAP poses. The cached sphere uses analytic synthetic depth and exact synthetic poses, not a learned prediction. Runtimes include the logged local stages with available caches; they do not measure dependency installation or internet downloads. All listed meshes are non-watertight.'),Table([[fig('temple_mono','colored_0.png',164,110),fig('temple_mono','shaded_0.png',164,110),fig('temple_mono','wireframe_0.png',164,110)]],colWidths=[167]*3),P('Temple mesh views: colored, shaded and triangle structure. The input photos are rolled; display orientation is corrected for these renders. Coverage is incomplete, and the learned depth produces smoothing and holes. No GT triangle model was supplied.','CaptionMesh'),P('Validation and reproducibility','SectionMesh'),P('The full project suite passed 36 tests, including nine mesh tests. Analytic gates cover robust inverse-depth alignment, sphere/box fusion, deliberate pose inversion, metric stereo depth, CPU ray-cast depth/normals, cleanup, color round trips, large-image consistency, and an offline relocated CLI/viewer run. Open3D 0.20 produced empty scalable-TSDF geometry in a plane diagnostic on this Mac; 0.19 was pinned and passed the gates.'),P('Depth Anything V2 Small uses its Apache-2.0 checkpoint at revision 5426e4f0f36572d16453bbda7a8389317b1bef99. Weights are not redistributed. Source hashes, configuration, seed, versions and accepted/skipped depth frames accompany each run.','CaptionMesh'),PageBreak()]
story += [P('Ablations and limitations','TitleMesh')]
a=json.loads((evidence/'ablations_sample/ablations.json').read_text());data=[['Tile-scene variant','State','Full triangles','Seconds']]
for r in a:data.append([r['name'],r['status'],f"{r['full']['faces']:,}" if r['status']=='complete' else '--',f"{r['seconds']:.2f}" if r['status']=='complete' else '--'])
story += [table(data,[180,80,130,110]),Spacer(1,10),P('These fixed-pose tile-scene runs compare learned versus SGBM depth, voxel divisions 128/256/384, consistency on/off and Poisson versus TSDF. The separate analytic fixture matrix is a numerical control and is not real-world reconstruction evidence.','CaptionMesh')]
f=json.loads((evidence/'failure_study/failure_study.json').read_text());data=[['Analytic sphere control','Views','Median error','95% error']]
for r in f['cases']:
 if r['status']=='complete':data.append([r['case'],str(r['views']),f"{r['median_surface_error']:.4f}",f"{r['p95_surface_error']:.4f}"])
story += [table(data,[220,60,110,110]),Spacer(1,10),P('Depth-scale errors are deliberately injected after alignment. Errors are distances from reconstructed vertices to the known unit-sphere surface, in synthetic units. Fewer views can retain accurate visible surfaces while sharply reducing coverage.','CaptionMesh'),Table([[Image(str(evidence/'failure_study/exact_12_views.png'),width=220,height=165),Image(str(evidence/'failure_study/all_depth_wrong_scale.png'),width=220,height=165)]],colWidths=[250,250]),P('Known sphere: correct depth (left) and all depths scaled incorrectly (right). These controlled failures complement the glossy-car example in the demo.','CaptionMesh'),P('Monocular depth inherits network smoothing and thickening. SGBM is unreliable on glossy, flat or repetitive regions. Sparse ROI percentiles can cut thin parts; the wider chair ROI mitigates this but can also retain more background. No unseen geometry was fabricated. Geometry agreement is not ground truth, and no real GT-mesh F-score mesh result is claimed.'),PageBreak()]
story += [P('Reproduce and integrate','TitleMesh'),P('Offline sample and viewer','SectionMesh'),Preformatted('python code/mesh/run_mesh.py \\\n  --scene sample_data/scene_small --out outputs/mesh \\\n  --config configs/mesh_default.yaml --cache-only\npython code/viz/view_mesh.py \\\n  --mesh outputs/mesh/mesh_light.ply\npython code/viz/view_mesh.py \\\n  --mesh outputs/mesh/mesh_light.ply --screenshot outputs/view.png\npython code/viz/render_mesh.py \\\n  --mesh outputs/mesh/mesh_light.ply --out outputs/renders --orbit',styles['CodeMesh'])]
fresh=json.loads((evidence/'fresh_machine.json').read_text());story += [P('Fresh-environment check','SectionMesh'),P('An isolated new virtual environment installed the pinned requirements. Relocated source reconstructed both shipped samples offline, rendered a mesh screenshot without OpenGL, and passed the mesh test suite. Exact commands, return codes and timings are retained in validation/mesh/fresh_machine.json. The final archive extraction check is recorded separately when packaging completes.'),P('The 30-second captioned mesh segment contains colored and shaded chair orbits, a wireframe close-up, our Temple mesh, the tile fixture and a glossy-car failure. It is ready to insert into the final 1-2 minute narrated demo. The review ZIP excludes raw datasets, weights and virtual environments, and enforces the 200 MiB archive and 40 MiB sample limits.'),P('References and credit','SectionMesh')]
refs=[('1','B. Curless and M. Levoy, A Volumetric Method for Building Complex Models from Range Images, SIGGRAPH, 1996.','https://graphics.stanford.edu/papers/volrange/'),('2','W. E. Lorensen and H. E. Cline, Marching Cubes: A High Resolution 3D Surface Construction Algorithm, SIGGRAPH, 1987, DOI 10.1145/37402.37422.','https://dl.acm.org/doi/10.1145/37402.37422'),('3','M. Kazhdan, M. Bolitho and H. Hoppe, Poisson Surface Reconstruction, Symposium on Geometry Processing, 2006.','https://diglib.eg.org/items/245d6ba1-0209-4365-a4a4-16ce46421620'),('4','L. Yang et al., Depth Anything V2, NeurIPS, 2024, arXiv:2406.09414.','https://arxiv.org/abs/2406.09414'),('5','Open3D 0.19: TSDF, marching cubes, Poisson, decimation, native viewing and CPU ray casting.','https://www.open3d.org/docs/0.19.0/'),('6','trimesh (OBJ/GLB export) and scikit-image (SSIM). Library API use; no copied implementations.','https://trimesh.org/'),('7','Middlebury multiview data for Temple. The synthetic chair and real car photos were supplied locally. No source GT mesh was supplied.','https://vision.middlebury.edu/mview/data/')]
for n,text,url in refs:story.append(P(f'[{n}] {text} <link href="{url}" color="#17364a">Source</link>.','CaptionMesh'))
